// The words of the language itself. Names of commands are not here: They are the runtime's business.
#pragma once
#include <string>
#include <string_view>

namespace blitz::tools {
	/** The spelling the manuals use for the keyword (If, EndIf, Wend), or an empty string if the word is not a keyword.
	 * The word is compared without regard to case.
	 */
	std::string_view keyword_spelling(std::string_view word);

	/** Keywords that are followed by a value, so that a - or + behind them is a sign and not a subtraction.
	 */
	bool keyword_takes_value(std::string_view lower_word);

	/** Keywords that work like a function and are written directly in front of the parenthesis: Int(x), Abs(x).
	 */
	bool keyword_is_function(std::string_view lower_word);

	/** Whether the word is the name of a type as it is written behind a colon (x:Int32, x:Float, x:String), in any case.
	 */
	bool is_type_name(std::string_view word);
} // namespace blitz::tools
